INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('azrbalm8s0lew58mkb90exazrbalkgfk', '2026-Q3', 'Set/2026 (T3)', '2026-09-18T17:35'::timestamptz, 'Marcio Yoshikatsu Medeiros Sakurata', 'marcio yoshikatsu medeiros sakurata', 'PHARUS', 'João Aliceda', 3.0, 'Detrator', 10.0, NULL, NULL, NULL, NULL, NULL, 'Estagnado ou travado', 'Entendi o método, mas ainda não implementei o suficiente', 'Participo do programa há alguns meses, mas os avanços têm sido limitados. Até o momento, consegui apenas iniciar o consórcio e não vi nenhuma outra oportunidade real do plano patrimonial sair do papel, o que me faz considerar a desistência.  Compreendo que certos processos exigem tempo, mas, nesse ritmo, não alcançaremos as metas estabelecidas. Vale destacar que o João é um excelente profissional, mas o escopo de atuação dele acaba ficando restrito pela falta de oportunidades disponíveis, como leilões, CCBs e investimentos no exterior.', 'Fazer o plano patrimonial proposta sair do papel', NULL, 'Ver que estamos evoluindo', 'Não', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'azrbalm8s0lew58mkb90exazrbalkgfk', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffi